bool HasCurrentMapSpawned()
{
	for (int i = 0; i < MAX_MAP_OBJECTS; i++)
	{
		if (DOES_OBJECT_EXIST(freeMem->m_map_mod.object[i])) 
			return true;
	}

	return false;
}

void AddMapModBlip(char* name, float x, float y, float z)
{
	if (DOES_BLIP_EXIST(freeMem->m_map_mod.blip))
		REMOVE_BLIP(freeMem->m_map_mod.blip);

	ADD_BLIP_FOR_COORD(x, y, z, &freeMem->m_map_mod.blip);
	CHANGE_BLIP_NAME_FROM_ASCII(freeMem->m_map_mod.blip, name);
	CHANGE_BLIP_ALPHA(freeMem->m_map_mod.blip, 255);
	CHANGE_BLIP_SPRITE(freeMem->m_map_mod.blip, 82);
	CHANGE_BLIP_COLOUR(freeMem->m_map_mod.blip, 11);
}

void TeleportToMapStart(float x, float y, float z, float h)
{
	SET_CHAR_COORDINATES(myPlayerPed, x, y, z);
	SET_CHAR_HEADING(myPlayerPed, h);
}

